  void RenderDualPose(){if(!DualReady||round==null||round.Dual==null)return;ActiveDualView.Present();displayedShot=ActiveDualView.View.FiringPose(0);if(displayedShot.Valid){muzzle.SetPositionAndRotation(From(displayedShot.Origin),Quaternion.LookRotation(From(displayedShot.Forward),From(displayedShot.Up)));displayedPoseValid=true;}}
