  sealed class DualPort:IR24DualCombatPort {readonly R23HandsWeapons host;internal DualPort(R23HandsWeapons actual){host=actual;}
   public bool Trace(Float3 origin,Float3 direction,float range,int hand,out R24DualContact contact){Vector3 a=From(origin),d=From(direction),end=a+d*range;contact=new R24DualContact();RaycastHit hit=new RaycastHit();Vector3 segment=a-host.head.transform.position;bool blocked=segment.sqrMagnitude>1e-6f&&host.Nearest(host.head.transform.position,segment.normalized,segment.magnitude,out hit);if(blocked){host.DualTrace(a,hit.point);contact.Point=To(hit.point);return true;}if(!host.Nearest(a,d,range,out hit)){host.DualTrace(a,end);return false;}host.DualTrace(a,hit.point);contact.Point=To(hit.point);contact.WorldCollider=hit.collider;foreach(var target in host.targets)if(target.Owns(hit.collider)){contact.TargetId=target.TargetId;contact.Head=hit.collider==target.Head;break;}if(host.impactMarks!=null)host.impactMarks.AddHit(hit.point,hit.normal,hit.collider);return true;}
